INSERT INTO feature VALUES('bicontextual-kernel-key','kernel','The kernel memo key on the binders a judgement reads','bicontextual-core','implemented','notable',NULL,'Every kernel node carries the free de Bruijn indices it mentions from its mint; the kernel''s check gathers each goal''s support from the binders its judgement read — the variables it looks up, the supports its subgoals and served entries carry, and those of the codes it owes — and records the goal''s memo entry over them, so one goal under two contexts that differ only where it did not read is one entry.','kernel-term kernel-check-memo kernel-core','corpus/ledger/features/bicontextual-kernel-key.gandr crates/kernel-term/src/support.rs crates/kernel-core-base/src/support.rs crates/kernel-core/tests/acceptance.rs','corpus/ledger/features/bicontextual-kernel-key.gandr','#3123');
